package org.pyslate.app;

import android.app.Instrumentation;
import android.os.Bundle;
import android.os.SystemClock;
import org.json.*;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;

/** Actual Binder/CPython stdin regression with production and test-only watchdog budgets. */
public final class InputInstrumentation extends Instrumentation {
    private ProjectStore store;private String id;private final JSONArray results=new JSONArray();
    private final class Run {
        final RunManager manager;final String runId;int cursor,exit=-999,requestId;boolean running=true,waiting;long started=SystemClock.elapsedRealtime();
        final StringBuilder out=new StringBuilder(),err=new StringBuilder();final JSONArray requestIds=new JSONArray();
        Run(RunManager manager,String code)throws Exception{this.manager=manager;store.call(new JSONObject().put("action","file.write").put("id",id).put("path","main.py").put("content",code));runId=manager.start(store.directory(id),"main.py").getString("runId");}
        void poll()throws Exception{JSONObject state=manager.call(new JSONObject().put("action","events").put("runId",runId).put("cursor",cursor));cursor=state.getInt("cursor");running=state.getBoolean("running");waiting=state.getBoolean("waiting");requestId=waiting?state.getInt("inputRequestId"):0;JSONArray events=state.getJSONArray("events");for(int i=0;i<events.length();i++){JSONObject event=events.getJSONObject(i);switch(event.getString("type")){case "stdout":out.append(event.optString("text"));break;case "stderr":err.append(event.optString("text"));break;case "input":if(event.has("requestId"))requestIds.put(event.getInt("requestId"));break;case "exit":exit=event.getInt("code");break;}}}
        void waitInput()throws Exception{long until=SystemClock.elapsedRealtime()+12000;do{poll();if(waiting)return;if(!running)throw new Exception("Program exited before input: "+err);SystemClock.sleep(25);}while(SystemClock.elapsedRealtime()<until);throw new Exception("No input request");}
        JSONObject submit(String text)throws Exception{return manager.call(new JSONObject().put("action","input").put("runId",runId).put("requestId",requestId).put("text",text));}
        boolean reject(int request,String text)throws Exception{try{manager.call(new JSONObject().put("action","input").put("runId",runId).put("requestId",request).put("text",text));return false;}catch(Exception expected){return true;}}
        void finish(long timeout)throws Exception{long until=SystemClock.elapsedRealtime()+timeout;do{poll();if(!running)return;SystemClock.sleep(25);}while(SystemClock.elapsedRealtime()<until);manager.call(new JSONObject().put("action","stop").put("runId",runId));throw new Exception("Program did not finish: "+out+err);}
        JSONObject detail()throws Exception{return new JSONObject().put("stdout",out.toString()).put("stderr",err.toString()).put("exit",exit).put("elapsedMs",SystemClock.elapsedRealtime()-started).put("requestIds",requestIds);}
        void close(){manager.close();SystemClock.sleep(450);}
    }
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){new Thread(()->{int failures=0;Run current=null;try{
        store=new ProjectStore(getTargetContext());id=store.call(new JSONObject().put("action","project.create").put("name","__input_v020_regressions__").put("practice",true)).getJSONObject("project").getString("id");
        current=new Run(new RunManager(getTargetContext()),"for i in range(3):\n    print(i, repr(input('值：')))\n");String[] lines={"中文","","最后"};for(String line:lines){current.waitInput();current.submit(line);}current.finish(6000);record("chinese_empty_consecutive",current.exit==0&&current.out.toString().equals("值：0 '中文'\n值：1 ''\n值：2 '最后'\n")&&current.requestIds.toString().equals("[1,2,3]"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext()),"a=input('一：')\nb=input('二：')\nprint(repr(a), repr(b))\n");current.waitInput();int first=current.requestId;boolean stale=current.reject(first+9,"错误"),multiline=current.reject(first,"a\nb");current.submit("first");boolean duplicate=current.reject(first,"duplicate");current.waitInput();boolean old=current.reject(first,"old");current.submit("");current.finish(6000);record("request_ids_stale_duplicate_multiline_rejected",stale&&duplicate&&old&&multiline&&current.exit==0&&current.out.toString().equals("一：二：'first' ''\n"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext()),"import sys\nprint('zero', repr(sys.stdin.readline(0)), repr(sys.stdin.read(0)))\nprint('done')\n");current.finish(12000);record("zero_length_reads_never_wait",current.exit==0&&current.requestIds.length()==0&&current.out.toString().equals("zero '' ''\ndone\n"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext()),"import sys\nprint(repr(sys.stdin.readline(2)))\nprint(repr(sys.stdin.readline()))\nprint(repr(sys.stdin.read(3)))\nprint(repr(sys.stdin.readline()))\n");current.waitInput();current.submit("abcd");current.waitInput();current.submit("xyz");current.finish(6000);record("partial_reads_preserve_remaining_line",current.exit==0&&current.requestIds.length()==2&&current.out.toString().equals("'ab'\n'cd\\n'\n'xyz'\n'\\n'\n"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext()),"import sys\nprint(repr(sys.stdin.read()))\nprint(repr(sys.stdin.readline()))\n");current.waitInput();current.submit("line");current.waitInput();current.manager.call(new JSONObject().put("action","input").put("runId",current.runId).put("requestId",current.requestId).put("eof",true));current.finish(6000);record("eof_finishes_bulk_read_and_remains_eof",current.exit==0&&current.requestIds.length()==2&&current.out.toString().equals("'line\\n'\n''\n"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext(),6500,1200),"input('等待：')\n");current.waitInput();current.finish(4000);record("input_wait_has_separate_timeout",current.exit==124&&current.err.toString().contains("等待输入超时"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext(),6500,15000),"import time\nstart=time.monotonic()\nwhile time.monotonic()-start < 1.5: pass\nx=input('思考：')\nprint('resumed', x)\nwhile True: pass\n");current.waitInput();SystemClock.sleep(7200);current.poll();boolean alive=current.running&&current.waiting;current.submit("继续");current.finish(10000);record("execution_budget_pauses_and_resumes_cumulatively",alive&&current.exit==124&&current.out.toString().contains("resumed 继续")&&current.err.toString().contains("累计执行超时"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext()),"print('收到', input('慢慢想：'))\n");current.waitInput();SystemClock.sleep(31500);current.poll();boolean productionAlive=current.running&&current.waiting;current.submit("31秒之后");current.finish(6000);record("production_input_survives_over_30_seconds",productionAlive&&current.exit==0&&current.out.toString().equals("慢慢想：收到 31秒之后\n"),current.detail());current.close();
        current=new Run(new RunManager(getTargetContext()),"input('可停止：')\n");current.waitInput();current.manager.call(new JSONObject().put("action","stop").put("runId",current.runId));current.finish(2000);record("stop_while_waiting",current.exit==130,current.detail());current.close();current=null;
    }catch(Throwable error){try{record("fatal",false,new JSONObject().put("error",error.toString()));}catch(Exception ignored){}}
    finally{if(current!=null)current.close();if(id!=null)try{store.call(new JSONObject().put("action","project.delete").put("id",id));}catch(Exception ignored){}try{for(int i=0;i<results.length();i++)if(!results.getJSONObject(i).getBoolean("pass"))failures++;JSONObject report=new JSONObject().put("platform","android").put("api",android.os.Build.VERSION.SDK_INT).put("device",android.os.Build.MODEL).put("productionExecutionTimeoutMs",30000).put("productionInputTimeoutMs",300000).put("failed",failures).put("results",results);Files.write(new File(getTargetContext().getFilesDir(),"android-input-v020.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));Bundle out=new Bundle();out.putString("stream",report.toString());finish(failures==0?-1:0,out);}catch(Exception error){Bundle out=new Bundle();out.putString("stream",error.toString());finish(0,out);}}},"PySlate-Input-Regression").start();}
    private void record(String name,boolean pass,JSONObject details)throws Exception{results.put(new JSONObject().put("name",name).put("pass",pass).put("details",details));Bundle progress=new Bundle();progress.putString("stream",name+" "+(pass?"PASS":"FAIL")+"\n");sendStatus(0,progress);}
}
